using FluentAssertions;
using PSXRecomp.Core.DiscImage;
using PSXRecomp.Core.Runtime.CdRom;

namespace PSXRecomp.Tests.DiscImageTests;

/// <summary>
/// Issue #10: BIN/CUE parsing and the <see cref="BinCueCdSectorSource"/> built on it. Every fixture is synthetic: a CUE
/// string and an in-memory BINARY file of generated bytes, with no commercial disc content.
/// </summary>
[Test]
public sealed class BinCueCdSectorSourceTests
{
    // Literal, not ICdSectorSource.RawSectorSize, so a change to the constant fails these tests (MINOR-6).
    private const int Raw = 2352;

    /// <summary>A BINARY file of <paramref name="sectors"/> raw sectors where every byte encodes its sector and offset.</summary>
    private static byte[] Bin(int sectors)
    {
        var bin = new byte[sectors * Raw];
        for (var i = 0; i < bin.Length; i++)
        {
            bin[i] = (byte)((i / Raw) * 7 + i);
        }

        return bin;
    }

    private const string TwoTrackCue =
        "FILE \"game.bin\" BINARY\r\n" +
        "  TRACK 01 MODE2/2352\r\n" +
        "    INDEX 00 00:00:00\r\n" +
        "    INDEX 01 00:02:00\r\n" +
        "  TRACK 02 AUDIO\r\n" +
        "    INDEX 00 00:30:00\r\n" +
        "    INDEX 01 00:32:00\r\n";

    [Fact]
    public void Open_TwoTrackCue_BuildsTocFromIndex01AndLeadOutAtFileEnd()
    {
        var bin = Bin(3000);

        var source = new BinCueCdSectorSource(TwoTrackCue, bin);

        // INDEX 01 00:02:00 is file index 150, so track 1 is LBA 0. INDEX 01 00:32:00 is file index 2400, so track 2
        // is LBA 2250. The lead-out is the file's 3000 sectors less 150, LBA 2850.
        source.Toc.Tracks.Should().Equal(new CdTrack(1, 0, false), new CdTrack(2, 2250, true));
        source.Toc.FirstTrack.Should().Be(1);
        source.Toc.LastTrack.Should().Be(2);
        source.Toc.LeadOutLba.Should().Be(2850);
    }

    [Fact]
    public void TryReadSector_InRange_ReadsFileIndexLbaPlus150()
    {
        var bin = Bin(3000);
        var source = new BinCueCdSectorSource(TwoTrackCue, bin);
        var destination = new byte[Raw];

        // LBA 2849 is the last sector before the lead-out, file index 2999.
        var found = source.TryReadSector(2849, destination);

        found.Should().BeTrue();
        destination.Should().Equal(bin.AsSpan(2999 * Raw, Raw).ToArray());
    }

    [Fact]
    public void TryReadSector_LbaZero_IsTheFileSectorAtIndex150()
    {
        var bin = Bin(3000);
        var source = new BinCueCdSectorSource(TwoTrackCue, bin);
        var destination = new byte[Raw];

        source.TryReadSector(0, destination).Should().BeTrue();
        destination.Should().Equal(bin.AsSpan(150 * Raw, Raw).ToArray());
    }

    [Fact]
    public void FileIndexAndLba_ConvertWithTheLeadInOfOneHundredFifty()
    {
        BinCueCdSectorSource.FileIndexToLba(150).Should().Be(0);
        BinCueCdSectorSource.FileIndexToLba(0).Should().Be(-150);
        BinCueCdSectorSource.LbaToFileIndex(0).Should().Be(150);
        BinCueCdSectorSource.LbaToFileIndex(-150).Should().Be(0);
        BinCueCdSectorSource.LeadInFrames.Should().Be(150);
        for (var fileIndex = 0; fileIndex < 1000; fileIndex += 37)
        {
            BinCueCdSectorSource.LbaToFileIndex(BinCueCdSectorSource.FileIndexToLba(fileIndex)).Should().Be(fileIndex);
        }
    }

    [Fact]
    public void TryReadSector_OutOfRange_ReturnsFalseAndLeavesDestinationUntouched()
    {
        var source = new BinCueCdSectorSource(TwoTrackCue, Bin(3000));
        var destination = Enumerable.Repeat((byte)0xAB, Raw).ToArray();

        source.TryReadSector(2850, destination).Should().BeFalse();
        source.TryReadSector(-1, destination).Should().BeFalse();
        destination.Should().OnlyContain(b => b == 0xAB);
    }

    [Fact]
    public void Parse_AcceptsCrlfBomLowercaseKeywordsQuotedNameRemAndPregapLines()
    {
        var cue = "﻿rem disc note\r\n" +
                  "file game.bin binary\r\n" +
                  "track 01 mode1/2352\r\n" +
                  "  pregap 00:02:00\r\n" +
                  "  index 01 00:02:00\r\n";

        var sheet = BinCueSheet.Parse(cue);

        sheet.Tracks.Should().Equal(new BinCueTrack(1, false, 150));
    }

    [Fact]
    public void Parse_IndexZeroAloneIsNotAStart_AndTrackWithoutIndexOneIsRejected()
    {
        var cue = "FILE \"g.bin\" BINARY\nTRACK 01 MODE2/2352\n INDEX 00 00:00:00\n";

        var act = () => BinCueSheet.Parse(cue);

        act.Should().Throw<InvalidDataException>().WithMessage("*no INDEX 01*");
    }

    [Theory]
    [InlineData("TRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", "*before FILE*")]
    [InlineData("FILE \"a.bin\" BINARY\nFILE \"b.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", "*second FILE*")]
    [InlineData("FILE \"a.bin\" WAVE\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", "*BINARY*")]
    [InlineData("FILE \"a.bin\" XBINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", "*BINARY*")]
    [InlineData("FILE \"a.bin\" BINARY\nINDEX 01 00:02:00\n", "*before any TRACK*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:75\n", "*MSF*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:60:00\n", "*MSF*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 1:2\n", "*MSF*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\nINDEX 01 00:03:00\n", "*more than one INDEX 01*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 00 MODE2/2352\nINDEX 01 00:02:00\n", "*not 1-99*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 99999999999:00:00\n", "*MSF*")]
    [InlineData("FILE \"a.bin\" BINARY\n", "*no TRACK*")]
    [InlineData("TRACK 01 MODE2/2352\n", "*before FILE*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\nTRACK 01 MODE2/2352\nINDEX 01 00:03:00\n", "*TRACK 01 does not follow TRACK 01*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 02 MODE2/2352\nINDEX 01 00:02:00\nTRACK 01 MODE2/2352\nINDEX 01 00:03:00\n", "*TRACK 01 does not follow TRACK 02*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\nTRACK 03 MODE2/2352\nINDEX 01 00:03:00\n", "*TRACK 03 does not follow TRACK 01*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\nINDEX 00 00:01:00\n", "*INDEX 00 after INDEX 01*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 00 00:03:00\nINDEX 01 00:02:00\n", "*greater than INDEX 01*")]
    [InlineData("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 00 00:00:00\nINDEX 00 00:01:00\nINDEX 01 00:02:00\n", "*more than one INDEX 00*")]
    public void Parse_MalformedSheet_ThrowsInvalidData(string cue, string message)
    {
        var act = () => BinCueSheet.Parse(cue);

        act.Should().Throw<InvalidDataException>().WithMessage(message);
    }

    [Fact]
    public void Parse_IndexZeroEqualToIndexOne_IsAccepted()
    {
        var cue = "FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 00 00:02:00\nINDEX 01 00:02:00\n";

        var sheet = BinCueSheet.Parse(cue);

        sheet.Tracks.Should().Equal(new BinCueTrack(1, false, 150));
    }

    [Fact]
    public void RawSectorSize_IsTheRawCdSectorOf2352Bytes()
    {
        ICdSectorSource.RawSectorSize.Should().Be(2352);
    }

    [Fact]
    public void TryReadSector_LeadOutAt149Sectors_LastSectorReadableAndNextAbsent()
    {
        // One track at file index 150 (LBA 0) over 299 file sectors: the lead-out is LBA 149.
        var source = new BinCueCdSectorSource("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", Bin(299));
        var destination = new byte[Raw];

        source.Toc.LeadOutLba.Should().Be(149);
        source.TryReadSector(148, destination).Should().BeTrue();
        source.TryReadSector(149, destination).Should().BeFalse();
    }

    [Fact]
    public void TryReadSector_DestinationShorterThanASector_ReturnsFalseWithoutWriting()
    {
        var source = new BinCueCdSectorSource(TwoTrackCue, Bin(3000));
        var destination = Enumerable.Repeat((byte)0xCD, Raw - 1).ToArray();

        source.TryReadSector(0, destination).Should().BeFalse();
        destination.Should().OnlyContain(b => b == 0xCD);
    }

    [Fact]
    public void Parse_NoFileLine_ThrowsInvalidData()
    {
        var act = () => BinCueSheet.Parse("REM only a comment\n");

        act.Should().Throw<InvalidDataException>().WithMessage("*no FILE*");
    }

    [Theory]
    [InlineData("MODE1/2048")]
    [InlineData("CDG")]
    [InlineData("MODE2/2336")]
    public void Parse_UnreadTrackMode_ThrowsNotSupported(string mode)
    {
        var cue = $"FILE \"a.bin\" BINARY\nTRACK 01 {mode}\nINDEX 01 00:02:00\n";

        var act = () => BinCueSheet.Parse(cue);

        act.Should().Throw<NotSupportedException>().WithMessage($"*'{mode}'*");
    }

    [Fact]
    public void Ctor_NullCue_ThrowsArgumentNull()
    {
        var act = () => new BinCueCdSectorSource(null!, Bin(10));

        act.Should().Throw<ArgumentNullException>();
    }

    [Theory]
    [InlineData(0)]
    [InlineData(Raw - 1)]
    [InlineData(Raw + 1)]
    public void Ctor_BinNotWholeRawSectors_ThrowsArgument(int length)
    {
        var act = () => new BinCueCdSectorSource("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", new byte[length]);

        act.Should().Throw<ArgumentException>().WithParameterName("bin");
    }

    [Fact]
    public void Ctor_IndexOneAtOrAfterFileEnd_ThrowsArgumentFromToc()
    {
        // Track 1 at file index 150 (LBA 0) in a 150-sector file: the lead-out is LBA 0, so the start is not before it.
        var act = () => new BinCueCdSectorSource("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", Bin(150));

        act.Should().Throw<ArgumentException>();
    }

    [Fact]
    public void Ctor_FewerThanTheLeadInSectors_ThrowsArgument()
    {
        var act = () => new BinCueCdSectorSource("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:02:00\n", Bin(149));

        act.Should().Throw<ArgumentException>().WithParameterName("bin").WithMessage("*lead-in*");
    }

    [Fact]
    public void Ctor_IndexOneBeforeTheLeadIn_ThrowsArgumentFromToc()
    {
        // INDEX 01 00:01:00 is file index 75, which would be LBA -75: the TOC does not accept a negative start.
        var act = () => new BinCueCdSectorSource("FILE \"a.bin\" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:01:00\n", Bin(300));

        act.Should().Throw<ArgumentException>();
    }
}
